def countPairs(nums, k):
    # Helper to compute gcd
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    from collections import defaultdict

    count = defaultdict(int)
    result = 0

    for num in nums:
        g = gcd(num, k)
        # For every previous gcd value, if their product is divisible by k,
        # count the pairs
        for prev_g, freq in count.items():
            if (g * prev_g) % k == 0:
                result += freq
        count[g] += 1
    return result
